--
-- Table structure for table `investment_details`
--

DROP TABLE IF EXISTS `investment_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `investment_details` (
  `investment_id` bigint NOT NULL AUTO_INCREMENT,
  `investor_id` bigint NOT NULL,
  `investment_amount` decimal(15,2) NOT NULL,
  `investment_date` date NOT NULL,
  `investment_mode` varchar(20) NOT NULL,
  `transaction_reference` varchar(100) DEFAULT NULL,
  `status` varchar(20) DEFAULT 'ACTIVE',
  `withdrawal_date` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `investment_type` varchar(20) NOT NULL DEFAULT 'NORMAL',
  PRIMARY KEY (`investment_id`),
  KEY `fk_investment_investor` (`investor_id`),
  CONSTRAINT `fk_investment_investor` FOREIGN KEY (`investor_id`) REFERENCES `investors` (`investor_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

